{
  "contract": "AmenoToken",
  "closure": {
    "site_function": "swapAndSendMarketingFee",
    "site_call": ".call",
    "functions": [
      "swapAndSendMarketingFee",
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions interact with pendingMarketingFee, which is exposed during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapAndSendMarketingFee",
    "pre": {
      "name": "pre",
      "from_marker": "PRE_START",
      "to_marker": "PRE_END"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "EXPOSED_START",
      "to_marker": "EXPOSED_END"
    },
    "post": {
      "name": "post",
      "from_marker": "POST_START",
      "to_marker": "POST_END"
    },
    "linearization_point": "EXPOSED_END"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The amount of pendingMarketingFee in-flight during the callback.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingMarketingFee == snapPre + inFlight",
    "stable_formula": "pendingMarketingFee == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "rule": "The exposure invariant ensures pendingMarketingFee is correctly accounted for during callbacks."
  }
}
